49		}
50		if errors.Is(err, ErrUnknownSuppression) || errors.Is(err, ErrUnknownBlock) || errors.Is(err, ErrUnknownVersion) {
51			t.Fatalf("corrupt report misreported as unknown suppression/block/version: %v", err)
52		}
53		msg := err.Error()
54		for _, sub := range want {
55			if !strings.Contains(msg, sub) {
56				t.Fatalf("error %q must name %q", msg, sub)
57			}
58		}
59		if changed {
60			t.Fatal("failed revocation reported a state change")
61		}
62		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
63			t.Fatal("failed revocation changed the archive")
64		}
65		// The condition kept its revoked flag. ListSuppressions cannot be
66		// asked here — its typed decode of the records trips over the corrupt
67		// declaration — so the flag is read off the raw archive document.
68		var doc struct {
69			Suppressions []Suppression `json:"suppressions"`
70		}
71		if err := json.Unmarshal(before, &doc); err != nil {
72			t.Fatal(err)
73		}
74		for _, c := range doc.Suppressions {
75			if c.ID == id && c.Revoked != wantRevoked {
76				t.Fatalf("failed revocation flipped the condition: %+v", c)
77			}
78		}
79		// The failure is not a write-side repair: revoking again fails the
80		// same way.
81		if _, _, err := RevokeSuppression(dir, id); !errors.Is(err, ErrCorruptVersion) {
82			t.Fatalf("second revoke did not fail the same way: %v", err)
83		}
84	}
85	
86	// TestRevokeCorruptSavedVersionRefused runs the full corruption matrix
87	// against the declaration embedded in the archived report: every way the
88	// saved document can stop satisfying the registration rules must fail the
89	// whole revocation with ErrCorruptVersion, naming chain, block, the saved
90	// id and the offending rule or field.
91	func TestRevokeCorruptSavedVersionRefused(t *testing.T) {
92		for _, tc := range corruptVersionCases {
93			t.Run(tc.name, func(t *testing.T) {
94				dir := setupRevokeCorruptArchive(t)
95				rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
96					tc.mutate(t, ver)
97				})
98				assertRevokeRefused(t, dir, "s1", false, "1", "0xblk", "candC", tc.wantErr)
99			})
100		}
101	}
102	
103	// TestRevokeNullAndEmptySavedVersionCorrupt pins the exact misread being
104	// fixed: a saved version:null used to decode into a nil pointer the save
105	// then dropped, rewriting the corrupt report into the legacy no-version
106	// shape a report query reads as built-in. Null, {}, an incomplete object
107	// and non-object declarations must all fail as corruption, and the failed
108	// revocation must leave the damaged declaration exactly as it was.
109	func TestRevokeNullAndEmptySavedVersionCorrupt(t *testing.T) {
110		cases := []struct {
111			name  string
112			value any
113		}{
114			{"null", nil},
115			{"empty object", map[string]any{}},
116			{"incomplete object", map[string]any{"id": "candC"}},
117			{"non-object number", 5},
118			{"non-object string", "builtin"},
119			{"array", []any{}},
120		}
121		for _, tc := range cases {
122			t.Run(tc.name, func(t *testing.T) {
123				dir := setupRevokeCorruptArchive(t)
124				replaceStoredReportVersion(t, dir, "1", "0xblk", tc.value)
125				assertRevokeRefused(t, dir, "s1", false, "1", "0xblk")
126				if tc.name == "null" {
127					// The written null survived the failed revocation as a
128					// null, not as a dropped version key.
129					text := string(readArchiveFile(t, dir))
130					if !strings.Contains(text, `"version": null`) {
131						t.Fatalf("failed revocation rewrote the null declaration:\n%s", text)
132					}
133				}
134			})
135		}
136	}
137	
138	// TestRevokeCorruptReportNeverSkipped proves the integrity proof covers
139	// every report in the archive: a decayed declaration fails the revocation
140	// even when the report sits on another chain, outside the condition's
141	// height coverage, or carries no conclusions at all.
142	func TestRevokeCorruptReportNeverSkipped(t *testing.T) {
143		t.Run("outside condition coverage", func(t *testing.T) {
144			// s1 covers heights 100-200; 0xblk sits at height 7 and its pool,
145			// kind and channel never match either — the decayed declaration
146			// still fails the revocation.
147			dir := setupRevokeCorruptArchive(t)
148			replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
149			assertRevokeRefused(t, dir, "s1", false, "1", "0xblk")
150		})
151	
152		t.Run("report on another chain", func(t *testing.T) {
153			dir := setupRevokeCorruptArchive(t)
154			mustReplay(t, dir, `{"chainId":"2","blockHash":"0xother","blockNumber":5,"swaps":[]}`)
155			replaceStoredReportVersion(t, dir, "2", "0xother", nil)
156			assertRevokeRefused(t, dir, "s1", false, "2", "0xother")
157		})
158	
159		t.Run("report without conclusions", func(t *testing.T) {
160			dir := setupRevokeCorruptArchive(t)
161			stripFindings(t, dir, "0xblk")
162			replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
163			assertRevokeRefused(t, dir, "s1", false, "1", "0xblk")
164		})
165	}
166	
167	// TestRevokeAlreadyRevokedStillProvesReports proves an idempotent
168	// re-revoke cannot mask existing damage: once the condition is registered
169	// the declarations are proved before the already-revoked state is
170	// reported, so a second revoke over a since-decayed report fails as
171	// corruption instead of returning changed:false.
172	func TestRevokeAlreadyRevokedStillProvesReports(t *testing.T) {
173		dir := setupRevokeCorruptArchive(t)
174		if _, changed, err := RevokeSuppression(dir, "s1"); err != nil || !changed {
175			t.Fatalf("first revoke: changed=%v err=%v", changed, err)
176		}
177		replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
178		assertRevokeRefused(t, dir, "s1", true, "1", "0xblk")
179	}
180	
181	// TestRevokeUnknownConditionOnCorruptArchive proves an id that was never
182	// registered keeps its existing error even when a stored report is
183	// corrupt: the declaration proof only runs for a registered condition.
184	func TestRevokeUnknownConditionOnCorruptArchive(t *testing.T) {
185		dir := setupRevokeCorruptArchive(t)
186		replaceStoredReportVersion(t, dir, "1", "0xblk", nil)
187		before := readArchiveFile(t, dir)
188		if _, _, err := RevokeSuppression(dir, "nope"); !errors.Is(err, ErrUnknownSuppression) {
189			t.Fatalf("got %v, want ErrUnknownSuppression", err)
190		}
191		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
192			t.Fatal("failed revocation changed the archive")
193		}
194	}
195	
196	// TestRevokeLegacyRecordWithoutVersionKey proves only a wholly absent
197	// version key keeps the built-in interpretation: the revocation succeeds
198	// and the legacy record is written back without growing a version key.
199	func TestRevokeLegacyRecordWithoutVersionKey(t *testing.T) {
200		dir := setupRevokeCorruptArchive(t)
201		dropVersionKey(t, dir, "0xblk")
202		cond, changed, err := RevokeSuppression(dir, "s1")
203		if err != nil || !changed {
204			t.Fatalf("legacy record must not block revocation: changed=%v err=%v", changed, err)
205		}
206		if !cond.Revoked {
207			t.Fatalf("revoked condition must carry revoked:true, got %+v", cond)
208		}
209		var doc struct {
210			Records []map[string]any `json:"records"`
211		}
212		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
213			t.Fatal(err)
214		}
215		for _, rec := range doc.Records {
216			if rec["blockHash"] == "0xblk" {
217				if _, ok := rec["version"]; ok {
218					t.Fatalf("legacy record grew a version key: %v", rec)
219				}
220			}
221		}
222	}
223	
224	// TestRevokeBuiltinIDDoesNotBypassValidation proves an id of "builtin" is
225	// validated like any other saved declaration: a complete one revokes
226	// normally, a damaged one fails as corruption rather than being replaced
227	// by the in-code builtin.
228	func TestRevokeBuiltinIDDoesNotBypassValidation(t *testing.T) {
229		dir := setupRevokeCorruptArchive(t)
230		builtinFull := map[string]any{
231			"id": "builtin",
232			"rules": map[string]any{
233				"sandwich":     map[string]any{"enabled": true, "severity": 3},
234				"displacement": map[string]any{"enabled": true, "severity": 2, "multiplier": 2},
235			},
236		}
237		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinFull)
238		if _, changed, err := RevokeSuppression(dir, "s1"); err != nil || !changed {
239			t.Fatalf("a complete builtin-id declaration must not block revocation: changed=%v err=%v", changed, err)
240		}
241	
242		dir = setupRevokeCorruptArchive(t)
243		builtinDamaged := map[string]any{
244			"id": "builtin",
245			"rules": map[string]any{
246				"sandwich":     map[string]any{"enabled": true, "severity": 3},
247				"displacement": map[string]any{"enabled": true, "severity": 2},
248			},
249		}
250		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinDamaged)
251		assertRevokeRefused(t, dir, "s1", false, BuiltinVersionID, "multiplier")
252	}
253	
254	// TestRevokeDuplicateFieldsInSavedVersionRefused covers decay registration
255	// could never have produced: a repeated field in the saved declaration,
256	// including a case-only spelling and an escaped spelling that name the
257	// same field — rejected even when both values agree. The raw bytes are
258	// patched directly because a JSON map cannot hold two keys.
259	func TestRevokeDuplicateFieldsInSavedVersionRefused(t *testing.T) {
260		cases := []struct{ name, field string }{
261			{"exact", `"severity": 4, `},
262			{"case variant", `"Severity": 4, `},
263			{"escaped", "\"se\\u0076erity\": 4, "},
264		}
265		for _, dup := range cases {
266			t.Run(dup.name, func(t *testing.T) {
267				dir := setupRevokeCorruptArchive(t)
268				path := filepath.Join(dir, archiveFileName)
269				text := string(readArchiveFile(t, dir))
270				// The first candC declaration in the file is the one embedded
271				// in the record (records precede the versions registry).
272				versionsAt := strings.Index(text, `"versions":`)
273				if versionsAt < 0 {
274					t.Fatal("versions section not found")
275				}
276				at := strings.Index(text[:versionsAt], `"id": "candC"`)
277				if at < 0 {
278					t.Fatal("record's embedded candC declaration not found")
279				}
280				anchor := `"severity": 4,`
281				field := strings.Index(text[at:versionsAt], anchor)
282				if field < 0 {
283					t.Fatal("severity field not found in embedded declaration")
284				}
285				pos := at + field
286				patched := text[:pos] + dup.field + text[pos:]
287				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
288					t.Fatal(err)
289				}
290				_, _, err := RevokeSuppression(dir, "s1")
291				if err == nil {
292					t.Fatal("duplicate-field declaration allowed the revocation")
293				}
294				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
295					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
296				}
297				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
298					t.Fatalf("error must name candC and severity, got %v", err)
299				}
300				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
301					t.Fatal("failed revocation repaired the duplicate field")
302				}
303			})
304		}
305	}
306	
307	// TestRevokeDisabledAndUnregisteredDeclarationsAccepted proves a legal
308	// declaration never blocks the revocation: an explicit enabled:false is a
309	// legal off state, and the saved id need not still be registered — the
310	// declaration is used exactly as saved, never completed from the enabled
311	// or a same-id registered version.
312	func TestRevokeDisabledAndUnregisteredDeclarationsAccepted(t *testing.T) {
313		dir := setupRevokeCorruptArchive(t)
314		ghost := map[string]any{
315			"id": "ghost",
316			"rules": map[string]any{
317				"sandwich":     map[string]any{"enabled": false, "severity": 1},
318				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 100},
319			},
320		}
321		replaceStoredReportVersion(t, dir, "1", "0xblk", ghost)
322		if _, changed, err := RevokeSuppression(dir, "s1"); err != nil || !changed {
323			t.Fatalf("unregistered but complete declaration must not block revocation: changed=%v err=%v", changed, err)
324		}
325		// The saved declaration survived the commit with its own parameters,
326		// never values pulled from the enabled or a same-id registered version.
327		text := string(readArchiveFile(t, dir))
328		if !strings.Contains(text, `"ghost"`) || !strings.Contains(text, `"multiplier": 100`) {
329			t.Fatalf("saved declaration was rewritten:\n%s", text)
330		}
331	}
332	
333	// TestRevokeSuccessChangesOnlyTheCondition proves a successful revocation
334	// touches nothing but the target condition's revoked flag: reports and
335	// their swap evidence, the versions registry, other conditions, existing
336	// processing records and reviews all survive byte for byte.
337	func TestRevokeSuccessChangesOnlyTheCondition(t *testing.T) {
338		dir := setupRevokeCorruptArchive(t)
339		// A second condition and a processed alert give the commit something to
340		// preserve beyond the target condition.
341		spec2 := `{"id":"a2","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":0,"endHeight":100,"reason":"r2"}`
342		if _, _, err := RegisterSuppression(dir, []byte(spec2)); err != nil {
343			t.Fatal(err)
344		}
345		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
346			t.Fatal(err)
347		}
348	
349		decode := func() map[string]any {
350			var doc map[string]any
351			if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
352				t.Fatal(err)
353			}
354			return doc
355		}
356		before := decode()
357		cond, changed, err := RevokeSuppression(dir, "s1")
358		if err != nil || !changed || !cond.Revoked {
359			t.Fatalf("revoke: changed=%v cond=%+v err=%v", changed, cond, err)
360		}
361		after := decode()
362	
363		for _, section := range []string{"records", "versions", "enabledVersion", "alerts"} {
364			if !reflect.DeepEqual(before[section], after[section]) {
365				t.Fatalf("revocation rewrote the %s section", section)
366			}
367		}
368		condsBefore, okB := before["suppressions"].([]any)
369		condsAfter, okA := after["suppressions"].([]any)
370		if !okB || !okA || len(condsBefore) != len(condsAfter) {
371			t.Fatalf("suppressions section changed shape: %v -> %v", before["suppressions"], after["suppressions"])
372		}
373		for i, cb := range condsBefore {
374			ca := condsAfter[i].(map[string]any)
375			cbm := cb.(map[string]any)
376			if cbm["id"] == "s1" {
377				if cbm["revoked"] != false || ca["revoked"] != true {
378					t.Fatalf("target condition's flag did not flip: %v -> %v", cbm, ca)
379				}
380				delete(cbm, "revoked")
381				delete(ca, "revoked")
382			}
383			if !reflect.DeepEqual(cbm, ca) {
384				t.Fatalf("condition %v changed beyond the revoked flag: %v", cbm, ca)
385			}
386		}
387	}
