28	// mustReplayDoc reads the archive at path into the raw-version document
29	// shape registration and replay use, leaving every stored version as its
30	// raw document.
31	func mustReplayDoc(t *testing.T, path string) replayArchiveDoc {
32		t.Helper()
33		raw, err := os.ReadFile(path)
34		if err != nil {
35			t.Fatal(err)
36		}
