44	// TestRegisterNewVersionPreservesCorruptSiblings runs the full corruption
45	// matrix against the siblings of a new registration: a legal spec for an
46	// unregistered ID must succeed (created:true) and be appended after the
47	// existing versions, while every corrupt stored declaration survives byte
48	// for byte, in order — and stays corrupt for enable, replay and compare.
49	func TestRegisterNewVersionPreservesCorruptSiblings(t *testing.T) {
50		for _, tc := range corruptVersionCases {
51			t.Run(tc.name, func(t *testing.T) {
52				dir := setupCorruptCompareArchive(t)
53				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
54					tc.mutate(t, ver)
55				})
56				before := readEnableSkeleton(t, dir)
57	
58				v, created, err := RegisterVersion(dir, []byte(freshVersionSpec))
59				if err != nil || !created {
60					t.Fatalf("registering a legal version past a corrupt sibling: v=%+v created=%v err=%v", v, created, err)
61				}
