68					t.Fatalf("version count = %d, want %d (append only)", len(after.Versions), len(before.Versions)+1)
69				}
70				if !reflect.DeepEqual(before.Versions, after.Versions[:len(before.Versions)]) {
71					t.Fatalf("existing declarations changed on registration:\nbefore=%s\nafter =%s",
72						before.Versions, after.Versions[:len(before.Versions)])
73				}
74				if after.EnabledVersion != before.EnabledVersion {
75					t.Fatalf("enabled marker changed on registration: %q -> %q", before.EnabledVersion, after.EnabledVersion)
76				}
77				if !reflect.DeepEqual(before.Records, after.Records) {
