1	package main
2	
3	// End-to-end regression coverage for `suppressions revoke` over an archive
4	// whose stored report carries a decayed rule-version declaration: the
5	// whole revocation must fail with exit code 1, no result JSON on stdout,
6	// an error naming the chain, block and the problem, and no change to the
7	// archive — the target condition keeps its revoked:false state and the
8	// damaged declaration is left exactly as it was.
9	
10	import (
11		"encoding/json"
12		"os"
13		"path/filepath"
14		"strings"
15		"testing"
16	)
17	
18	// setupCorruptRevokeCLIArchive archives two blocks on chain "1" — 0xok at
19	// height 10 with a sandwich conclusion, 0xdecayed at height 20 with no
20	// swaps — registers suppression condition s1, then rewrites 0xdecayed's
21	// embedded version declaration to null and deletes the source input file.
22	func setupCorruptRevokeCLIArchive(t *testing.T) string {
